#include <stdio.h>

int main(void) {
    char word[64];
    int k;

    if (scanf("%s", word) != 1) {
        return 1;
    }
    if (scanf("%d", &k) != 1) {
        return 1;
    }

    printf("改之前：%s\n", word);
    word[k] = '{up}';
    printf("改之后：%s\n", word);
    return 0;
}
